// src/components/AdminStudentsFees.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast from "react-hot-toast";

export default function AdminStudentsFees({ student, onClose }) {
  if (!student) return null; 
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [feeData, setFeeData] = useState({});
  const [paid, setPaid] = useState(0);

  // ---------- CLASS BASED STRUCTURE ----------
  const getBaseStructure = (cls) => {
    const c = parseInt(cls);

    if (c >= 1 && c <= 5) return ["development", "transport"];
    if (c >= 6 && c <= 9) return ["tuition", "development", "transport"];

    return ["exam", "tuition", "development"];
  };

  // ---------- INITIAL LOAD ----------
  useEffect(() => {
    if (!student) return;

    const base = getBaseStructure(student.classApplied);

    const server = student.feeOverrides || {};

    // merge base + server
    const merged = {};

    base.forEach((t) => {
      merged[t] = server[t] ?? 0;
    });

    Object.keys(server).forEach((t) => {
      merged[t] = server[t];
    });

    setFeeData(merged);
    setPaid(student.paidFee || 0);
  }, [student]);

  // ---------- ADD EXTRA TYPE ----------
  const addNewType = () => {
    const name = prompt("Enter new fee type name:");

    if (!name) return;

    if (feeData[name]) {
      return toast.error("This fee type already exists!");
    }

    setFeeData((p) => ({ ...p, [name]: 0 }));
  };

  // ---------- DELETE EXTRA TYPE ----------
  const deleteType = (key) => {
    const base = getBaseStructure(student.classApplied);

    if (base.includes(key)) {
      return toast.error("Base class structure fee cannot be deleted!");
    }

    const copy = { ...feeData };
    delete copy[key];
    setFeeData(copy);
  };

  // ---------- SAVE CHANGES ----------
  const saveChanges = async () => {
    setSaving(true);

    try {
      // IMPORTANT:
      // Backend expects: feeOverrides: { key: Number }
      const cleaned = {};
      for (const k in feeData) {
        cleaned[k] = Number(feeData[k]) || 0;
      }

      const res = await axios.put(
        `http://localhost:5000/api/admin/update-student-fees/${student._id}`,
        {
          feeOverrides: cleaned,   // <-- backend compatible
        }
      );

      toast.success("Saved successfully!");

      onClose();
    } catch (err) {
      console.log(err);
      toast.error("Save failed!");
    }

    setSaving(false);
  };

  // ---------- TOTALS ----------
  const total = Object.values(feeData).reduce(
    (sum, x) => sum + (Number(x) || 0),
    0
  );

  const remaining = total - paid;

  return (
    <div className="fee-editor">
      <h2>
        Edit Fees — {student.studentName} (Class {student.classApplied})
      </h2>

      <button onClick={addNewType} className="add-btn">
        + Add Fee Type
      </button>

      <button
        onClick={() => window.location.reload()}
        style={{ marginLeft: "10px" }}
      >
        Reset to server values
      </button>

      <table className="fee-table">
        <thead>
          <tr>
            <th>Fee Type</th>
            <th>Amount (₹)</th>
          </tr>
        </thead>

        <tbody>
          {Object.keys(feeData).map((key) => {
            const isExtra =
              !getBaseStructure(student.classApplied).includes(key);

            return (
              <tr key={key}>
                <td>
                  {key}
                  {isExtra && (
                    <span
                      className="delete-icon"
                      onClick={() => deleteType(key)}
                      style={{ cursor: "pointer", marginLeft: "6px" }}
                    >
                      🗑
                    </span>
                  )}
                </td>

                <td>
                  <input
                    type="number"
                    value={feeData[key]}
                    onChange={(e) =>
                      setFeeData({
                        ...feeData,
                        [key]: e.target.value,
                      })
                    }
                  />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <div className="totals">
        <p><b>Total:</b> ₹{total}</p>
        <p><b>Paid:</b> ₹{paid}</p>
        <p><b>Remaining:</b> ₹{remaining}</p>
      </div>

      <button
        className="save-btn"
        onClick={saveChanges}
        disabled={saving}
      >
        {saving ? "Saving..." : "Save Changes"}
      </button>
    </div>
  );
}
